package app.moneytracker.domain.ai

import java.io.File
import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertTrue

/**
 * The Kotlin Smart entry engine must give the same answers as the training prototype on 690 English, Hinglish and Hindi
 * sentences (noisy speech-style examples generated by Codex plus the original dictation set), using the shipped model files.
 */
class SmartParserGoldenTest {
    private val assets = File("src/androidMain/assets/smart")
    private val parser by lazy { SmartParser.load { name -> File(assets, name).readBytes() } }

    @Suppress("UNCHECKED_CAST")
    @Test fun matchesPrototypeAnswers() {
        val gold = MiniJsonForTest.parse(javaClass.getResource("/smart/golden.json")!!.readText()) as Map<String, Any?>
        val accounts = gold["accounts"] as List<String>
        val cases = gold["cases"] as List<Map<String, Any?>>
        val expense = listOf("Food", "Groceries", "Transport", "Travel", "Housing", "Bills", "Subscriptions", "Entertainment", "Shopping",
            "Personal care", "Health", "Education", "Gifts", "Family", "Finance", "Other")
        val income = listOf("Salary", "Business", "Bonus", "Interest", "Allowance", "Refund/Cashback", "Other")
        val same = HashMap<String, Int>().withDefault { 0 }
        val diffs = ArrayList<String>()
        val t0 = System.nanoTime()
        for (c in cases) {
            val r = parser.parse(c["text"] as String, expense, income, accounts)
            val checks = mapOf(
                "tokens" to (r.words.map { it.first } == c["tokens"]),
                // Rules on top of the tagger may only turn words into the account ("on my credit card"), never anything else.
                "tags" to r.words.map { it.second }.zip(c["tags"] as List<String>).all { (k, p) -> k == p || k == "ACC" },
                "type" to (r.type == c["type"]),
                "amount" to ((c["amount"] as Double?)?.let { r.amount != null && abs(r.amount!! - it) < 1e-6 } ?: (r.amount == null)),
                "daysAgo" to (r.daysAgo == (c["daysAgo"] as Double).toInt()),
                "account" to (r.account == c["account"]),
                "top1" to (r.categories.firstOrNull()?.name == (c["top3"] as List<String>).firstOrNull()),
                "top3" to (r.categories.take(3).map { it.name } == c["top3"]),
            )
            checks.forEach { (k, ok) -> if (ok) same[k] = same.getValue(k) + 1 }
            if (checks.values.any { !it } && diffs.size < 25) diffs.add("${c["text"]}\n   kotlin=${r.type} ${r.amount} ${r.account} ${r.categories.take(3).map { it.name }} ${r.words}\n   python=${c["type"]} ${c["amount"]} ${c["account"]} ${c["top3"]} ${c["tags"]}")
        }
        val ms = (System.nanoTime() - t0) / 1e6
        val n = cases.size
        val report = same.keys.sorted().joinToString { "$it ${same.getValue(it)}/$n" }
        println("SMART PARITY: $report · ${"%.2f".format(ms / n)} ms per sentence (JVM, first run includes setup)")
        diffs.forEach { println(it) }
        for (k in listOf("tokens", "tags", "type", "amount", "daysAgo", "account")) assertTrue(same.getValue(k) >= n * 0.99, "$k: $report")
        assertTrue(same.getValue("top1") >= n * 0.97, "top1: $report")
    }

    /** Notes use the words as heard, not the model's simplified spelling ("aayi" stays "aayi"); Hindi script becomes Latin letters. */
    @Test fun notesKeepWordsAsHeard() {
        val cats = listOf("Food", "Transport", "Entertainment")
        val r = parser.parse("2 dahi puri 50 aur chaat 30 hdfc se", cats, listOf("Salary"), listOf("HDFC"))
        assertTrue(r.itemsHeard.size == r.items.size && r.itemsHeard.isNotEmpty(), "${r.items} / ${r.itemsHeard}")
        assertTrue(r.itemsHeard.first() == "dahi puri", "${r.itemsHeard}")
        val h = parser.parse("कल पेट्रोल 500 का डलवाया", cats, listOf("Salary"), listOf("HDFC"))
        assertTrue(h.itemsHeard.firstOrNull() == "petrol", "${h.itemsHeard}")
        val m = parser.parse("200 for movie tickets", cats, listOf("Salary"), listOf("HDFC"))
        assertTrue(m.itemsHeard.firstOrNull() == "movie tickets", "${m.items} / ${m.itemsHeard}")
    }

    /** Everyday English, the main way people talk to it: card phrases are the account, never the note or a random card. */
    @Test fun everydayEnglish() {
        val ex = listOf("Food", "Groceries", "Transport", "Travel", "Bills", "Subscriptions", "Entertainment", "Shopping", "Personal care", "Health", "Gifts", "Other")
        val inc = listOf("Salary", "Bonus", "Refund/Cashback", "Other")
        val oneCard = listOf("Cash", "HDFC Credit Card", "SBI Account", "GPay")
        val twoCards = listOf("SBI Cashback", "HDFC", "Scapia", "Slice Card", "CSB edge Jupyter card")
        fun p(t: String, accounts: List<String> = oneCard) = parser.parse(t, ex, inc, accounts)

        p("1,200 for new shoes on my credit card yesterday").let {
            assertTrue(it.type == "expense" && it.amount == 1200.0 && it.daysAgo == 1, "$it")
            assertTrue(it.itemsHeard == listOf("new shoes"), "${it.itemsHeard}")
            assertTrue(it.categories.first().name == "Shopping", "${it.categories}")
            assertTrue(it.account == "HDFC Credit Card", it.account)   // the only credit card
        }
        assertTrue(p("1,200 for new shoes on my credit card", twoCards).account == "", "several cards: don't guess")
        assertTrue(p("Spent 450 on groceries with my HDFC card").let { it.account == "HDFC Credit Card" && it.itemsHeard == listOf("groceries") })
        // "cash" is an account called Cash, not "SBI Cashback"; a hesitant income guess with no income word is spending.
        p("Doctor visit 700 cash", twoCards).let { assertTrue(it.account == "" && it.type == "expense", "$it") }
        assertTrue(p("Doctor visit 700 cash").account == "Cash")
        assertTrue(p("Got my salary 50,000").let { it.type == "income" && it.itemsHeard == listOf("salary") })
        // The card is the subject here, not how it was paid.
        assertTrue(p("Got 200 credit card cashback").itemsHeard == listOf("credit card cashback"))
        p("Paid my credit card bill 12,000 from SBI").let { assertTrue(it.account == "SBI Account" && it.itemsHeard == listOf("credit card"), "$it") }
        assertTrue(p("Bought a gift card for 500").itemsHeard == listOf("gift card"))
    }
}
